        failure = NetworkException(message="connection refused")
        auth = _create_authenticator()
        mock_client = MagicMock()
        mock_client.send_request.side_effect = failure
        auth.set_api_client(mock_client)

        with pytest.raises(NetworkException) as excinfo:
            auth.build_authorization_url()

        assert excinfo.value is failure


