class TestOidcPkceAndInvalidation:
    def test_bhv_misc_078_the_authorization_url_carries_an_s256_challenge_and_no_nonce(
        self,
    ) -> None:
        auth, _ = _create_authenticator_with_discovery()

        params = parse_qs(urlparse(auth.build_authorization_url()).query)

        assert params["code_challenge_method"] == ["S256"]
        assert re.fullmatch(r"[A-Za-z0-9_-]{43}", params["code_challenge"][0])
        assert "nonce" not in params

    def test_bhv_authoidc_021_a_rediscovery_that_names_new_endpoints_keeps_the_verifier(
        self,
    ) -> None:
        from unittest.mock import patch

        auth = _create_authenticator()
        mock_client = MagicMock()
        endpoints = {"token_endpoint": "https://auth.example.com/token"}

        def respond(
            method: str, url: str, *args: Any, **kwargs: Any
        ) -> ApiHttpResponse:
            if url.endswith("openid-configuration"):
                return ApiHttpResponse(
                    status_code=200,
                    body=json.dumps(
                        {
                            "authorization_endpoint": "https://auth.example.com/authorize",
                            "token_endpoint": endpoints["token_endpoint"],
                        }
                    ),
                    headers={
                        "content-type": "application/json",
                        "cache-control": "max-age=100",
                    },
                )
            return ApiHttpResponse(
                status_code=200,
                body=json.dumps({"access_token": "at", "expires_in": 3600}),
                headers={"content-type": "application/json"},
            )

        mock_client.send_request.side_effect = respond
        auth.set_api_client(mock_client)
        module = "petstore_client.auth.oauth.openid_connect_authenticator.time"

        with patch(module) as clock:
            clock.monotonic.return_value = 1000.0
            params = parse_qs(urlparse(auth.build_authorization_url()).query)
            endpoints["token_endpoint"] = "https://auth.example.com/moved/token"
            clock.monotonic.return_value = 1100.0
            auth.exchange_code("the-code")

        token_call = mock_client.send_request.call_args
        assert token_call[0][1] == "https://auth.example.com/moved/token"
        verifier = parse_qs(token_call[0][3])["code_verifier"][0]
        digest = hashlib.sha256(verifier.encode("ascii")).digest()
        challenge = base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
        assert challenge == params["code_challenge"][0]

    def test_bhv_auth_002_invalidating_before_any_discovery_does_nothing(self) -> None:
        auth, mock_client = _create_authenticator_with_discovery()

        auth.invalidate_access_token()

        mock_client.send_request.assert_not_called()

    def test_bhv_authoidc_015_a_dropped_token_is_replaced_by_a_refresh(self) -> None:
        auth, mock_client = _create_authenticator_with_discovery()
        auth.build_authorization_url()
        mock_client.send_request.side_effect = [
            ApiHttpResponse(
                status_code=200,
                body=json.dumps(
                    {"access_token": "t1", "refresh_token": "r1", "expires_in": 3600}
                ),
                headers={"content-type": "application/json"},
            ),
            ApiHttpResponse(
                status_code=200,
                body=json.dumps({"access_token": "t2", "expires_in": 3600}),
                headers={"content-type": "application/json"},
            ),
        ]
        auth.exchange_code("c")
        assert auth.get_auth_headers() == {"Authorization": "Bearer t1"}

        auth.invalidate_access_token()

        assert auth.get_auth_headers() == {"Authorization": "Bearer t2"}
        assert "refresh_token=r1" in mock_client.send_request.call_args[0][3]
